#pragma once
#include <SDL2/SDL.h>
#include <stdint.h>
#include "ms800.h"

/*
 * SDL2 front-panel UI, laid out to match a real MS800 unit photo:
 * charcoal fascia, red 2-digit display, "DIGITAL WAVE SYNTHESIZER"
 * caption, power rocker, and 10 buttons in a 2x5 grid with the real
 * printed labels. The wordmark reads "CHEETAR MS800" on purpose.
 *
 *   CHANNEL   PATCH   ^   ^^   NEXT PARAM
 *   FUNCTION  PARAM   v   vv   ENTER
 *
 * (top row above each button, bottom row below — as on the real unit.)
 */

#include "panel_layout.h"   /* generated by tools/gen_panel_art.py */

#define BTN_COLS 5

void ui_panel_init(SDL_Renderer *ren);
/* Draws the panel: key-down state comes from the machine's buttons. */
void ui_panel_draw(SDL_Renderer *ren, const ms800_t *m, uint8_t display_byte, int powered_on);

/* Returns the MS800_BTN_* hit at (x,y), or 0 if none. */
int ui_panel_hit_test_button(int x, int y);

/* Returns 1 if (x,y) is within the power switch hit area. */
int ui_panel_hit_test_power(int x, int y);
